from pathlib import Path
from http.server import ThreadingHTTPServer,SimpleHTTPRequestHandler
from functools import partial
from threading import Thread
from playwright.sync_api import sync_playwright
import json
P=Path(__file__).parent;server=ThreadingHTTPServer(('127.0.0.1',0),partial(SimpleHTTPRequestHandler,directory=str(P)));Thread(target=server.serve_forever,daemon=True).start();errors=[]
try:
 with sync_playwright() as pw:
  browser=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':1150,'height':1300});page.on('pageerror',lambda e:errors.append(str(e)));page.goto(f'http://127.0.0.1:{server.server_port}/review.html');page.wait_for_function('window.annexReady===true');sizes=page.locator('canvas').evaluate_all('a=>a.map(c=>({cssWidth:c.clientWidth,cssHeight:c.clientHeight,bufferWidth:c.width,bufferHeight:c.height}))');assert sizes[0]['cssWidth']==144
  # Actual live renderer past completion: root must hold; global pose clock must continue.
  page.evaluate('window.annexController.setMode("snappy")');page.wait_for_timeout(1650);live=page.evaluate('''()=>new Promise(resolve=>{const r=[];let begin;function take(t){if(begin===undefined)begin=t;r.push({sampleMs:t-begin,...window.currentDartState});if(t-begin<240)requestAnimationFrame(take);else resolve(r)}requestAnimationFrame(take)})''');assert all(s['root']==[36,0] and s['terminal'] for s in live);assert len({s['frameId'] for s in live})==4;assert live[-1]['poseTick']>live[0]['poseTick']
  page.evaluate('window.annexController.pause()');controlTimes=[1,34,67,101,401,434,601,634,800,1500,1534,1567,1601,5000];controls=page.evaluate('ts=>ts.map(t=>window.annexController.sampleAt(t))',controlTimes);assert len({s['frameId'] for s in controls[:8]})==8
  hashes=page.evaluate('''async ts=>{const rows=[];for(const t of ts){const state=window.annexController.sampleAt(t);const c=document.querySelector('#yard'),pixels=c.getContext('2d').getImageData(0,0,c.width,c.height).data;const digest=await crypto.subtle.digest('SHA-256',pixels);rows.push({elapsedMs:t,frameId:state.frameId,root:state.root,pivot:state.pivot,pixelSHA256:Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('')})}return rows}''',controlTimes[:8]);assert len({r['pixelSHA256'] for r in hashes})==8
  stale=page.evaluate('''()=>{const c=window.annexController,old=c.generation();c.replay();const token=c.generation();const before=JSON.stringify(c.current());const rejected=c.callbackForTest(performance.now()+10000,old);const after=JSON.stringify(c.current());const valid=c.callbackForTest(performance.now(),token);c.pause();return{staleRejected:rejected===false,staleDidNotChangeState:before===after,validCallbackAccepted:valid===true,oldGeneration:old,newGeneration:token}}''');assert stale['staleRejected'] and stale['staleDidNotChangeState'] and stale['validCallbackAccepted'];page.wait_for_timeout(100)
  stableBefore=page.evaluate('JSON.stringify(window.currentDartState)');page.wait_for_timeout(80);stableAfter=page.evaluate('JSON.stringify(window.currentDartState)');assert stableBefore==stableAfter
  page.get_by_role('button',name='Dark ground').click();dark=page.locator('#yard').evaluate('c=>getComputedStyle(c).backgroundColor');assert dark=='rgb(23, 34, 31)';page.get_by_role('button',name='Light ground').click();light=page.locator('#yard').evaluate('c=>getComputedStyle(c).backgroundColor');assert light=='rgb(217, 212, 189)';page.select_option('#mode','original');page.evaluate('window.annexController.pause()');slow=page.evaluate('window.annexController.sampleAt(1100)');assert slow['root'][0]<36;assert not errors;browser.close()
 r={'passed':True,'method':'actual Chromium canvas uses unchanged B atlas and pivots; byte buffers hashed then discarded, no captures saved','sizes':sizes,'birdCanvasWorldAndCSSPixels':64,'actualTerminalHoldRecords':live,'distinctTerminalWingFrames':len({s['frameId'] for s in live}),'numericPoseRootControls':controls,'actualCanvasPixelHashControls':hashes,'staleRAFCallbackControls':stale,'pausedRendererStableAfterStaleCallbacks':stableBefore==stableAfter,'lightDarkControls':{'light':light,'dark':dark},'originalModeControlAt1100ms':slow,'pageErrors':errors,'browserCaptureBytesSaved':False,'newDrawings':0,'appBound':False};(P/'browser-verification.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({k:r[k] for k in ['passed','distinctTerminalWingFrames','staleRAFCallbackControls','pageErrors']}))
finally:server.shutdown();server.server_close()
